function update(){frame++;if(state!=='play')return;let dir=(keys.arrowright||keys.d||keys.right?1:0)-(keys.arrowleft||keys.a||keys.left?1:0);player.vx=dir*1.65;if(dir)player.face=dir;player.x=Math.max(0,Math.min(2390,player.x+player.vx));player.vy=Math.min(7,player.vy+.28);let oldY=player.y;player.y+=player.vy;player.ground=false;for(const p of platforms){if(player.x+11>p.x&&player.x+4<p.x+p.w&&oldY+player.h<=p.y+2&&player.y+player.h>=p.y&&player.vy>=0){player.y=p.y-player.h;player.vy=0;player.ground=true}}
if(player.y>H+20){hurt(true)}if(player.inv>0)player.inv--;if(player.throwing>0)player.throwing--;player.anim+=Math.abs(player.vx)*.16;
for(const c of coinList){if(!c.got&&Math.abs(player.x+8-c.x)<12&&Math.abs(player.y+10-c.y)<15){c.got=true;coins++;$('#coinCount').textContent=String(coins).padStart(2,'0');sfx('coin')}}
for(const e of enemies){if(!e.alive)continue;let p=platformAt(e.x,225);let plat=platforms.find(q=>e.x+9>q.x&&e.x-9<q.x+q.w&&Math.abs(q.y- e.y)<5);if(!plat){plat=platforms.find(q=>e.x+9>q.x&&e.x-9<q.x+q.w&&q.y>=e.y&&q.y-e.y<8)}if(!plat){let q=platforms.find(q=>e.x+8>q.x&&e.x-8<q.x+q.w&&q.x>e.x-30);if(q)plat=q}if(plat){e.y=plat.y-20;let min=plat.x+10,max=plat.x+plat.w-10;e.x+=e.dir*.42;if(e.x<min||e.x>max)e.dir*=-1}else{e.y=222}if(player.inv===0&&Math.abs(player.x+8-e.x)<17&&Math.abs(player.y+12-e.y)<18){if(player.vy>1&&player.y+20<e.y+9){e.alive=false;player.vy=-4;sfx('enemy')}else hurt(false)}}
for(let i=projectiles.length-1;i>=0;i--){let s=projectiles[i];s.x+=s.vx;s.life--;s.rot+=.4;for(const e of enemies)if(e.alive&&Math.abs(e.x-s.x)<11&&Math.abs(e.y+9-s.y)<12){e.alive=false;s.life=0;sfx('enemy');break}if(s.life<=0)projectiles.splice(i,1)}camera=Math.max(0,Math.min(1960,player.x-132));$('#progressText').textContent=Math.min(100,Math.floor(player.x/2390*100))+'%';if(player.x>2370)finish(true)}
function hurt(fall){if(player.inv>0)return;health--;updateHealth();player.inv=100;player.vy=fall?-1:-3;player.x=Math.max(10,player.x-12);sfx('hit');if(health<=0)finish(false)}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(Math.round(x),Math.round(y),r,0,Math.PI*2);ctx.fill()}
function drawSky(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1d3345');g.addColorStop(.58,'#536675');g.addColorStop(1,'#e3a978');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);circle(385,60,22,'#f3d9aa');circle(385,60,18,'#f2dfb6');for(const s of stars){if(Math.sin(frame*.025+s.phase)>.1)rect(s.x,s.y,s.s,s.s,'#f3dfb2aa')}
// mountain layered silhouettes
ctx.fillStyle='#80909a';ctx.beginPath();ctx.moveTo(180,175);ctx.lineTo(284,63);ctx.lineTo(309,84);ctx.lineTo(342,43);ctx.lineTo(422,176);ctx.fill();ctx.fillStyle='#d3c9b3';ctx.beginPath();ctx.moveTo(276,72);ctx.lineTo(284,63);ctx.lineTo(294,72);ctx.lineTo(287,68);ctx.lineTo(283,76);ctx.fill();ctx.fillStyle='#596c78';ctx.beginPath();ctx.moveTo(245,174);ctx.lineTo(340,48);ctx.lineTo(436,174);ctx.fill();ctx.fillStyle='#e3d7c1';ctx.beginPath();ctx.moveTo(325,68);ctx.lineTo(340,48);ctx.lineTo(355,68);ctx.lineTo(344,63);ctx.lineTo(338,72);ctx.fill();
// distant layered hills
for(let i=0;i<5;i++){ctx.fillStyle=['#536d74','#506b70','#425c63','#49665f','#39554d'][i];ctx.beginPath();ctx.moveTo(0,177+i*4);for(let x=0;x<=W;x+=40){let yy=164+i*6+Math.sin((x+i*71)*.022)*8;ctx.lineTo(x,yy)}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill()}
// distant village and fields
for(let i=0;i<9;i++){let x=i*67-(camera*.16%67),y=169+(i%3)*6;rect(x,y,25,21,'#674b4b');rect(x-3,y-4,31,7,'#3b4145');rect(x+4,y+7,5,8,'#d7ad78');rect(x+16,y+7,5,6,'#edc78d')}
// bamboo silhouettes
for(let i=0;i<8;i++){let x=((i*79-camera*.28)%560+560)%560-20;let height=53+(i*29%42);rect(x,174-height,3,height,'#314b47');for(let j=0;j<3;j++){let yy=177-height+j*17;rect(x-8,yy,8,2,'#52705c');rect(x+3,yy+7,10,2,'#52705c')}rect(x-2,177-height,7,3,'#58735e')}
// torii in distance
for(const tx of [100,333]){let x=tx-camera*.21;rect(x,145,3,33,'#8e4e43');rect(x+25,145,3,33,'#8e4e43');rect(x-5,142,40,4,'#ae6650');rect(x-2,137,34,4,'#ae6650')}
}

function drawTree(x,y,sc=1){ctx.save();ctx.translate(x,y);ctx.scale(sc,sc);rect(-2,-24,5,26,'#594a3e');for(const [a,b,r] of [[-8,-28,9],[1,-35,11],[10,-28,8],[-1,-43,7]]){circle(a,b,r,'#df8a91');circle(a-3,b-3,r*.6,'#f0a6a2');circle(a+5,b+3,2,'#ffd7af')}for(let i=0;i<5;i++){circle(-10+i*5,-17+(i%2)*3,1,'#ffcb9c')}ctx.restore()}
function drawWorld(){drawSky();for(let x=45;x<530;x+=205){drawTree(x-camera*.39,205,.8)}
// near torii gate
let tx=620-camera*.7;if(tx>-60&&tx<520){rect(tx+12,146,7,70,'#713c37');rect(tx+57,146,7,70,'#713c37');rect(tx,143,77,8,'#a95f4c');rect(tx+7,137,63,7,'#c47b58');rect(tx+18,146,4,14,'#dc9d6c');rect(tx+57,146,4,14,'#dc9d6c')}
// platforms
for(const p of platforms){let x=p.x-camera;if(x+p.w<0||x>W)continue;if(p.type==='stone'){rect(x,p.y,p.w,48,'#625f5a');rect(x,p.y,p.w,5,'#a99a7c');for(let bx=0;bx<p.w;bx+=23){rect(x+bx,p.y+15,20,2,'#77736a');rect(x+bx+9,p.y+27,15,2,'#4b4c49');rect(x+bx+2,p.y+4,2,8,'#c0aa86')}}else{rect(x,p.y,p.w,7,'#9b6345');rect(x,p.y+7,p.w,6,'#704836');rect(x,p.y,p.w,2,'#d19a61');for(let bx=12;bx<p.w;bx+=20){rect(x+bx,p.y+2,2,3,'#574130');circle(x+bx+1,p.y+5,1,'#dcaa6b')}}}
// cherry trees along path
for(const tx of [183,756,1190,1680,2072]){let x=tx-camera;if(x>-40&&x<520)drawTree(x,platforms.find(p=>Math.abs(p.x-tx)<80)?.y||214,1.0)}
// coins
for(const c of coinList){if(c.got)continue;let x=c.x-camera;if(x<-10||x>W+10)continue;let bob=Math.sin(frame*.09+c.phase)*2;circle(x,c.y+bob,5,'#f6c966');circle(x,c.y+bob,3,'#ffec9d');rect(x-1,c.y+bob-3,2,6,'#dc9c43');circle(x-1,c.y+bob-1,1,'#fff0bd')}
// enemies
for(const e of enemies){if(!e.alive)continue;let x=e.x-camera;if(x<-20||x>W+20)continue;drawSamurai(x,e.y,e.dir)}
// shuriken projectiles
for(const s of projectiles){let x=s.x-camera;ctx.save();ctx.translate(x,s.y);ctx.rotate(s.rot);ctx.fillStyle='#d9e0db';ctx.beginPath();for(let i=0;i<8;i++){let a=i*Math.PI/4,r=i%2===0?7:2;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();circle(0,0,1.4,'#58636b');ctx.restore()}
drawPlayer(player.x-camera,player.y);
// foreground grass/pebbles
for(let i=0;i<60;i++){let x=(i*83-camera*.93%83+W)%W;rect(x,264-(i%3),2,3,['#65835f','#85946a','#b58b68'][i%3])}
}
function drawSamurai(x,y,dir){let bob=Math.sin(frame*.12+x)*.5;rect(x-7,y+6+bob,14,9,'#694951');rect(x-8,y+12+bob,6,6,'#d5b68f');rect(x+2,y+12+bob,6,6,'#d5b68f');rect(x-5,y+18+bob,5,2,'#332f38');rect(x+1,y+18+bob,5,2,'#332f38');rect(x-6,y-3+bob,12,10,'#9c4650');rect(x-6,y-8+bob,12,9,'#d0a47e');rect(x-7,y-12+bob,14,5,'#3b3e49');rect(x-5,y-15+bob,11,4,'#454952');rect(x-3+(dir<0?-1:1),y-5+bob,3,2,'#25272c');rect(x-9,y-4+bob,3,6,'#b86a59');rect(x+6,y-4+bob,3,6,'#b86a59');rect(x+7,y-8+bob,2,14,'#ddd0b0')}
function drawPlayer(x,y){if(player.inv>0&&Math.floor(frame/5)%2===0)return;let run=player.ground?Math.sin(player.anim)*2:0,bob=player.ground?Math.abs(Math.sin(player.anim))*1.5:0;let footA=run,footB=-run; // shadow
ctx.fillStyle='#17263080';ctx.beginPath();ctx.ellipse(x+8,player.y+23,9,2,0,0,Math.PI*2);ctx.fill();
// legs and sandals
rect(x+3+footA,y+16-bob,4,5,'#26333c');rect(x+9+footB,y+16-bob,4,5,'#26333c');rect(x+2+footA,y+20-bob,6,2,'#bc7954');rect(x+8+footB,y+20-bob,6,2,'#bc7954');
// body scarf and sleeves
rect(x+3,y+8-bob,10,9,'#263a4d');rect(x+2,y+9-bob,12,3,'#36536a');rect(x+1,y+10-bob,4,6,'#263a4d');rect(x+11,y+10-bob,4,5,'#263a4d');rect(x+3,y+14-bob,10,2,'#d5a35b');rect(x+6,y+14-bob,2,2,'#f0ca7a');
// face
rect(x+4,y+2-bob,9,8,'#e8bd92');rect(x+3,y+1-bob,11,4,'#202d3b');rect(x+2,y+2-bob,3,5,'#263846');rect(x+12,y+4-bob,3,4,'#263846');rect(x+5,y+5-bob,2,2,'#273241');rect(x+10,y+5-bob,2,2,'#273241');rect(x+7,y+8-bob,4,2,'#b75252');rect(x+2,y-bob,12,3,'#9e494b');rect(x+5,y-3-bob,6,3,'#c36a5b');rect(x+1,y+3-bob,3,2,'#d38768');
// flowing headband
if(player.face>0){rect(x+12,y+1-bob,6,2,'#d17c63');rect(x+16,y+2-bob,4,2,'#e3a06f')}else{rect(x-3,y+1-bob,6,2,'#d17c63');rect(x-5,y+2-bob,4,2,'#e3a06f')}
// arm/throw pose
if(player.throwing>4){rect(x+(player.face>0?12:-2),y+9-bob,5,3,'#263a4d');rect(x+(player.face>0?15:-4),y+8-bob,3,3,'#e8bd92')}
}
function render(){ctx.clearRect(0,0,W,H);drawWorld()}
function loop(t){if(t-lastTick>16){update();render();lastTick=t}requestAnimationFrame(loop)}
requestAnimationFrame(loop);
})();
</script>
</body></html>

