(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=480,H=270;ctx.imageSmoothingEnabled=false;
const $=s=>document.querySelector(s),hud=$('#hud'),startOverlay=$('#startOverlay'),pauseOverlay=$('#pauseOverlay'),endOverlay=$('#endOverlay');let state='title',camera=0,frame=0,coins=0,health=3,audioCtx=null,musicTimer=null,musicOn=true,lastTick=0;
const keys={},platforms=[{x:0,y:222,w:185,type:'stone'},{x:218,y:201,w:92,type:'wood'},{x:342,y:222,w:148,type:'stone'},{x:512,y:192,w:88,type:'wood'},{x:638,y:213,w:108,type:'stone'},{x:790,y:184,w:100,type:'wood'},{x:926,y:219,w:128,type:'stone'},{x:1085,y:195,w:104,type:'wood'},{x:1225,y:216,w:114,type:'stone'},{x:1376,y:187,w:96,type:'wood'},{x:1515,y:218,w:150,type:'stone'},{x:1704,y:192,w:116,type:'wood'},{x:1858,y:218,w:115,type:'stone'},{x:2006,y:197,w:100,type:'wood'},{x:2140,y:222,w:300,type:'stone'}];
const coinXs=[116,257,386,552,683,833,973,1137,1273,1412,1571,1757,1910,2054,2260],coinList=coinXs.map((x,i)=>({x,y:[180,160,181,150,173,143,177,163,174,146,176,154,176,158,181][i],got:false,phase:i*1.7})),enemies=[{x:435,dir:-1,alive:true},{x:704,dir:1,alive:true},{x:1015,dir:-1,alive:true},{x:1303,dir:1,alive:true},{x:1620,dir:-1,alive:true},{x:1890,dir:1,alive:true},{x:2200,dir:-1,alive:true}];const player={x:42,y:175,vx:0,vy:0,w:15,h:23,ground:false,face:1,inv:0,anim:0,throwing:0};let stars=[];for(let i=0;i<45;i++)stars.push({x:(i*97+21)%W,y:(i*53+13)%155,s:i%4===0?2:1,phase:i*.7});
function reset(){Object.assign(player,{x:42,y:175,vx:0,vy:0,ground:false,face:1,inv:0,anim:0,throwing:0});camera=0;coins=0;health=3;coinList.forEach(c=>c.got=false);enemies.forEach(e=>e.alive=true);projectiles.length=0;$('#coinCount').textContent='00';updateHealth()}
function start(){if(state==='play')return;reset();state='play';hud.classList.add('active');startOverlay.classList.add('hidden');pauseOverlay.classList.add('hidden');endOverlay.classList.add('hidden');startMusic()}
function pause(){if(state==='play'){state='pause';pauseOverlay.classList.remove('hidden');stopMusic()}else if(state==='pause'){state='play';pauseOverlay.classList.add('hidden');startMusic()}}
function finish(win){state='end';hud.classList.remove('active');endOverlay.classList.remove('hidden');$('#endLabel').textContent=win?'A little more of the world':'The road goes on';$('#endTitle').textContent=win?'Well traveled.':'Rest, little ninja.';$('#endText').textContent=win?`You found ${coins} lost coins. The mountain is closer now.`:`You gathered ${coins} coins along the old road.`;stopMusic()}
function updateHealth(){$('#health').innerHTML='♥ '.repeat(Math.max(0,health)).trim()||'—'}
function audio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx}
function tone(freq,duration,type='sine',vol=.025,delay=0){if(!musicOn)return;const a=audio(),o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,a.currentTime+delay);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+delay+duration);o.connect(g);g.connect(a.destination);o.start(a.currentTime+delay);o.stop(a.currentTime+delay+duration)}
function sfx(k){if(!musicOn)return;if(k==='jump'){tone(392,.12,'triangle',.045);tone(587,.18,'sine',.03,.055)}if(k==='coin'){tone(784,.09,'sine',.035);tone(1175,.18,'sine',.025,.07)}if(k==='throw'){tone(660,.07,'square',.018);tone(440,.1,'triangle',.02,.04)}if(k==='hit'){tone(180,.2,'sawtooth',.035);tone(110,.25,'triangle',.035,.07)}if(k==='enemy'){tone(330,.12,'triangle',.025);tone(220,.19,'sine',.02,.09)}}
const scaleNotes=[392,440,523,587,659,784,880,1047,784,659,587,523,440,392,523,659];let beat=0;
